def gen(rng):
    def fmt(a):
        return f'{len(a)}\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([0]), fmt([3, 1]), fmt([1, 3]), fmt([2, 2, 2]), fmt([10**6] * 6),
             fmt([1, 10**6, 1]), fmt([4, 1, 1, 4]), fmt([0, 0, 0, 7, 0])]
    for n in (3, 4, 5, 6, 8, 10, 12, 20, 30, 40):
        for _ in range(2):
            hi = rng.choice([3, 9, 100, 10**6])
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    N = 1500
    tests.append(fmt([rng.randint(0, 10**6) for _ in range(N)]))
    tests.append(fmt([10**6] * N))
    tests.append(fmt([rng.randint(1, 10) for _ in range(N)]))
    tests.append(fmt(sorted(rng.randint(0, 10**6) for _ in range(N))))
    return tests
